// Canvas fallback for devices where WebGL is disabled. The experience remains animated.
export function createFallback(container){
 const canvas=document.createElement('canvas');container.append(canvas);const c=canvas.getContext('2d',{alpha:false});let w=1,h=1,scale=1;let seed=45;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const stars=Array.from({length:100},()=>[random(),random()*.5,random()]);
 const blocks=[];for(let x=-4;x<=4;x++)for(let z=-4;z<=4;z++){if(x===0||z===0)continue;blocks.push({x:x*42,z:z*42,w:27+random()*9,d:27+random()*9,h:25+random()*55,r:random(),color:['#4b5666','#596170','#66747e','#4f5265'][Math.floor(random()*4)]});}blocks.sort((a,b)=>b.x+b.z-a.x-a.z);
 function sky(t,night,day){const horizon=h*.535;const grad=c.createLinearGradient(0,0,0,horizon);grad.addColorStop(0,night?'#080f27':day?'#3f86ad':'#496675');grad.addColorStop(.7,night?'#1b2843':day?'#9ec7d2':'#a4acaa');grad.addColorStop(1,night?'#354353':day?'#cfdfd7':'#ddbe95');c.fillStyle=grad;c.fillRect(0,0,w,horizon+2);const sx=w*.69,sy=h*(day?.24:.492);const glow=c.createRadialGradient(sx,sy,2,sx,sy,w*.32);glow.addColorStop(0,night?'#d9e4ff40':'#ffe4b4aa');glow.addColorStop(.2,night?'#d9e4ff08':'#f4ce9f44');glow.addColorStop(1,'transparent');c.fillStyle=glow;c.fillRect(0,0,w,horizon);c.fillStyle=night?'#dce5eb':'#fff0c9';c.beginPath();c.arc(sx,sy,night?4:9,0,Math.PI*2);c.fill();if(night){for(const [x,y,r]of stars){c.fillStyle=`rgba(230,238,255,${.15+r*.6})`;c.fillRect(x*w,y*h,1,1);}}else{c.save();c.globalAlpha=.11;for(let i=0;i<9;i++){const x=((i*.16+t*.0006)%1.5-.2)*w,y=h*(.14+(i%4)*.075);const g=c.createRadialGradient(x,y,1,x,y,w*.2);g.addColorStop(0,'#e9e5d7');g.addColorStop(1,'transparent');c.fillStyle=g;c.save();c.translate(0,y);c.scale(1,.12);c.fillRect(x-w*.2,-w*.2,w*.4,w*.4);c.restore();}c.restore();}return horizon;}
 function sea(t,s,d,intensity,yaw,pitch){const night=s===1||d===2,day=d===1;const horizon=sky(t,night,day);const seaGrad=c.createLinearGradient(0,horizon,0,h);seaGrad.addColorStop(0,night?'#27384a':day?'#6d9fa6':'#a2a99d');seaGrad.addColorStop(.35,night?'#0f2337':day?'#316c7b':'#3d626a');seaGrad.addColorStop(1,night?'#091b2c':day?'#164759':'#173c4a');c.fillStyle=seaGrad;c.fillRect(0,horizon,w,h-horizon);const tt=t*intensity;
  for(let row=0;row<320;row++){const p=row/320,y=horizon+Math.pow(p,2.1)*(h-horizon),depth=(y-horizon)/(h-horizon);const amp=(.2+depth*4.5)*intensity;const wavelength=3+depth*130;const frequency=w/wavelength;const offset=tt*(.6+depth)*13;const light=(Math.sin(row*1.92+tt*.4)+Math.sin(row*.35-tt*.8))*.5;const brightness=Math.floor(90+light*36);c.strokeStyle=night?`rgba(80,110,144,${.07+depth*.2})`:`rgba(${brightness+12},${brightness+35},${brightness+40},${.15+depth*.28})`;c.lineWidth=.3+depth*1.9;c.beginPath();for(let x=0;x<=w+8;x+=8){const wave=Math.sin(x/wavelength+offset+row*.9)*amp+Math.sin(x/wavelength*.43-offset*.7)*amp*.55;if(x===0)c.moveTo(x,y+wave);else c.lineTo(x,y+wave);}c.stroke();const sunx=w*(.69+yaw*.02);const spread=6+depth*w*.24;for(let j=0;j<4;j++){const q=Math.sin(row*7.6+j*54.2)*.5+.5;const x=sunx+Math.sin(row*2.3+j*5.4+tt*.8)*spread;const a=(1-depth*.5)*(.1+q*.22);c.fillStyle=night?`rgba(154,180,211,${a*.5})`:`rgba(255,225,170,${a})`;c.fillRect(x,y+Math.sin(row+tt)*amp,1+q*depth*38,.4+depth);}}
  if(s===2){const shore=h*.76+Math.sin(tt*.48)*h*.026;const sand=c.createLinearGradient(0,shore,0,h);sand.addColorStop(0,night?'#383c43':'#8b9a8b');sand.addColorStop(.2,night?'#424348':'#bcaa83');sand.addColorStop(1,night?'#55505a':'#e5ce9f');c.fillStyle=sand;c.beginPath();c.moveTo(-10,h);c.lineTo(-10,shore);for(let x=0;x<w+10;x+=8)c.lineTo(x,shore+Math.sin(x/w*4.4+tt*.27)*h*.025+(x/w-.5)*h*.1);c.lineTo(w+10,h);c.closePath();c.fill();for(let k=0;k<3;k++){c.strokeStyle=night?'#a2b8c733':`rgba(236,245,226,${.45-k*.12})`;c.lineWidth=3-k*.5;c.beginPath();for(let x=0;x<w+10;x+=3){const yy=shore+Math.sin(x/w*4.4+tt*.27)*h*.025+(x/w-.5)*h*.1-k*7+Math.sin(x*.07+tt)*2+Math.sin(x*.2)*1.5;if(!x)c.moveTo(x,yy);else c.lineTo(x,yy);}c.stroke();}seed=45;c.fillStyle=night?'#ffffff03':'#70523510';for(let i=0;i<1800;i++){const x=random()*w,y=shore+random()*(h-shore);if(y>shore+40)c.fillRect(x,y,.8,.8);}}
 }
 function city(t,d,yaw,pitch){
  const night=d===2;const grad=c.createLinearGradient(0,0,0,h);grad.addColorStop(0,night?'#101b36':d===1?'#739caf':'#596278');grad.addColorStop(1,night?'#2b3046':'#a2958e');c.fillStyle=grad;c.fillRect(0,0,w,h);const unit=Math.min(w/270,h/210);const angle=.72+yaw*.3,cs=Math.cos(angle),sn=Math.sin(angle);const project=(x,y,z)=>{const a=x*cs-z*sn,b=x*sn+z*cs;const distance=440-b;const f=440/distance;return [w*.55+a*unit*f,h*.48+(b*.83-y*(.4+pitch*.12))*unit*f];};
  function polygon(points,fill){c.fillStyle=fill;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();}function plane(x,y,z,ww,dd,col){polygon([project(x-ww/2,y,z-dd/2),project(x+ww/2,y,z-dd/2),project(x+ww/2,y,z+dd/2),project(x-ww/2,y,z+dd/2)],col);}
  plane(0,-1,0,700,700,night?'#343b48':'#64676c');plane(0,0,0,42,700,'#292e39');plane(0,.01,0,700,40,'#292e39');
  for(let i=-300;i<300;i+=12){plane(0,.03,i,.3,5,'#b6b4a0');plane(i,.03,0,5,.3,'#b6b4a0');}
  for(let i=-22;i<=22;i+=2.8){plane(i,.05,i,7,1.3,'#d7d9d1');plane(-i,.05,i,7,1.3,'#d7d9d1');plane(-24,.06,i,8,1.3,'#d7d9d1');plane(24,.06,i,8,1.3,'#d7d9d1');plane(i,.06,-23,1.3,8,'#d7d9d1');plane(i,.06,23,1.3,8,'#d7d9d1');}
  const phase=t%38;for(let i=0;i<240;i++){const lane=i%4;const q=phase<24?Math.max(0,Math.min(1,(phase/24*1.5-(i%23)/23*.48))):1;const offset=Math.sin(i*7)*4;let x=-25+q*50,z=-24+q*48;if(lane===1)x=25-q*50;if(lane===2){x=-24+offset;z=-20+q*40;}if(lane===3){x=-20+q*40;z=24+offset;}const p=project(x+offset,1,z);c.fillStyle=['#d9c9b5','#24354b','#535768','#aa7f72'][i%4];c.fillRect(p[0],p[1],Math.max(1,unit*.7),unit*1.6);c.fillStyle='#ddbaa1';c.beginPath();c.arc(p[0]+unit*.3,p[1]-.3,unit*.28,0,Math.PI*2);c.fill();}
  for(let i=0;i<20;i++){let dist=(t*5+i*25)%500-250;if(phase<24&&Math.abs(dist)<48)dist=50+(i%5)*8;const axis=i%2;plane(axis?dist:8,.5,axis?8:dist,axis?4.2:1.8,axis?1.8:4.2,['#dedbcc','#bbb18e','#72868e','#202b3c'][i%4]);}
  // Painter-sorted building faces with inset window grids.
  const draw=[...blocks].sort((a,b)=>{const da=a.x*sn+a.z*cs,db=b.x*sn+b.z*cs;return da-db;});
  for(const b of draw){const x=b.x,z=b.z,bw=b.w/2,bd=b.d/2,hh=b.h;const back=project(x-bw,0,z-bd),right=project(x+bw,0,z-bd),front=project(x+bw,0,z+bd),left=project(x-bw,0,z+bd);const tb=project(x-bw,hh,z-bd),tr=project(x+bw,hh,z-bd),tf=project(x+bw,hh,z+bd),tl=project(x-bw,hh,z+bd);polygon([left,front,tf,tl],b.color);polygon([right,front,tf,tr],night?'#26364b':'#424e60');polygon([tb,tr,tf,tl],night?'#3d475a':'#849099');for(let yy=4;yy<hh-2;yy+=4.8)for(let xx=-bw+2;xx<bw-1;xx+=4){const lit=Math.sin(xx*2+yy*7+b.r*68)>.0;const color=lit?(night?'#d9b87d':'#91a6ab'):'#344656';polygon([project(x+xx,yy,z+bd+.05),project(x+xx+2,yy,z+bd+.05),project(x+xx+2,yy+2,z+bd+.05),project(x+xx,yy+2,z+bd+.05)],color);polygon([project(x+bw+.05,yy,z+xx),project(x+bw+.05,yy,z+xx+2),project(x+bw+.05,yy+2,z+xx+2),project(x+bw+.05,yy+2,z+xx)],color);}plane(x,hh+.2,z,5,6,'#9a9c9b');if(Math.abs(x)<90&&Math.abs(z)<90){const a=project(x-bw+1,hh*.38,z+bd+.3),b1=project(x+bw-1,hh*.38,z+bd+.3),cc=project(x+bw-1,hh*.7,z+bd+.3),dd=project(x-bw+1,hh*.7,z+bd+.3);polygon([a,b1,cc,dd],['#b74c69','#377d9d','#d9926d'][Math.abs(Math.floor(x))%3]);c.save();c.beginPath();[a,b1,cc,dd].forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.clip();c.fillStyle='#fff2d9';c.font=`bold ${Math.max(9,unit*4)}px Arial`;c.fillText('SHIBUYA / '+['MUSIC','TOKYO','LIVE'][Math.floor(t*.2)%3],dd[0]+Math.sin(t)*4,dd[1]+(a[1]-dd[1])*.6);c.restore();}}
 }
 return {domElement:canvas,setPixelRatio(v){scale=v;},setSize(ww,hh){w=ww;h=hh;canvas.width=Math.floor(w*scale);canvas.height=Math.floor(h*scale);c.setTransform(scale,0,0,scale,0,0);},draw(s,t,d,intensity,yaw,pitch){if(s===3)city(t,d,yaw,pitch);else sea(t,s,d,intensity,yaw,pitch);}};
}
